window.HYDRA_SEARCH = [{"url":"index.html","label":"Hydra reference","kind":"Page","description":"A compact guide to the implemented language and standard library."},{"url":"builtins.html#print","label":"print","kind":"Function","description":"print(value, terminator = \"\\n\") — Write one value as text, followed by terminator. Use \"\" to omit the newline."},{"url":"builtins.html#len","label":"len","kind":"Function","description":"len(value) — Count list elements, dict entries, or Unicode characters in a string."},{"url":"builtins.html#has","label":"has","kind":"Function","description":"has(container, key) — Test for a dict key or list index. Negative indices count from the end."},{"url":"builtins.html#get","label":"get","kind":"Function","description":"get(container, key, fallback) — Read a dict key or list index, returning fallback when absent. Does not insert anything."},{"url":"builtins.html#push","label":"push","kind":"Function","description":"push(&list, value) — Append a copied value to a list; return its new length. The list argument must use &."},{"url":"builtins.html#return","label":"return","kind":"Function","description":"return(values*) — Construct a return request. Unconsumed, return its payload from the current function; an empty request returns :null."},{"url":"builtins.html#break","label":"break","kind":"Function","description":"break() — Construct a loop-stop request. Unconsumed, stop the nearest loop in this function; a parallel loop stops as a whole."},{"url":"builtins.html#continue","label":"continue","kind":"Function","description":"continue() — Construct an iteration-stop request. Unconsumed, skip the rest of this iteration; a parallel iteration ends its trail."},{"url":"builtins.html#reject","label":"reject","kind":"Function","description":"reject(msg = :null) — Construct a rejection. Unconsumed in a function, try its next overload. Unhandled exhaustion reports all refusal messages and fails."},{"url":"builtins.html#exit","label":"exit","kind":"Function","description":"exit(code = 0) — Construct an exit request. Unconsumed, stop the program with an integer status from 0 through 255."},{"url":"builtins.html#panic","label":"panic","kind":"Function","description":"panic(msg) — Construct a panic request. Unconsumed, stop the program with a rendered message, call trace, and status 1."},{"url":"builtins.html#alive","label":"alive","kind":"Function","description":"alive() — Whether the current trail is still live. Returns :true outside a trail."},{"url":"builtins.html#channel","label":"channel","kind":"Function","description":"channel() — The current trail’s zero-based index in its block. Requires a trail."},{"url":"builtins.html#send","label":"send","kind":"Function","description":"send(value, to*, mode = :wait) — Send to sibling trails; omit destinations for any sibling. Default :wait waits for receipt; :detach queues one message; :broadcast queues a copy per eligible sibling. False if none remain. Requires a trail."},{"url":"builtins.html#receive","label":"receive","kind":"Function","description":"receive(from*) — Wait for a sibling’s message and its sender index. Omit sources for any sibling. Returns :null, :null once none can send. Requires a trail."},{"url":"builtins.html","label":"Builtins","kind":"Page","description":"Global functions, available without an import."},{"url":"fs.html#join","label":"fs::join","kind":"Function","description":"join(base, parts*) — Join and normalize path components. join(\"a\", \"/b\") yields \"a/b\". Removes .; preserves ..."},{"url":"fs.html#parent","label":"fs::parent","kind":"Function","description":"parent(path) — Parent directory; \".\" if the path has no directory component."},{"url":"fs.html#name","label":"fs::name","kind":"Function","description":"name(path) — Final path component, including its extension."},{"url":"fs.html#stem","label":"fs::stem","kind":"Function","description":"stem(path) — Final component without its last extension."},{"url":"fs.html#extension","label":"fs::extension","kind":"Function","description":"extension(path) — Last extension without its dot; \"\" if absent."},{"url":"fs.html#absolute","label":"fs::absolute","kind":"Function","description":"absolute(path) — Resolve against the working directory. Does not require existence or resolve symlinks."},{"url":"fs.html#cwd","label":"fs::cwd","kind":"Function","description":"cwd() — Current working directory."},{"url":"fs.html#home","label":"fs::home","kind":"Function","description":"home() — Current user’s home directory. Crashes if unavailable."},{"url":"fs.html#temp","label":"fs::temp","kind":"Function","description":"temp() — System temporary directory. Does not create a file or directory."},{"url":"fs.html#exists","label":"fs::exists","kind":"Function","description":"exists(path) — Whether the path exists and can be inspected. Follows symlinks."},{"url":"fs.html#is_file","label":"fs::is_file","kind":"Function","description":"is_file(path) — Whether the path is a regular file. False if absent or inaccessible."},{"url":"fs.html#is_dir","label":"fs::is_dir","kind":"Function","description":"is_dir(path) — Whether the path is a directory. False if absent or inaccessible."},{"url":"fs.html#size","label":"fs::size","kind":"Function","description":"size(path) — Size from filesystem metadata, in bytes. Without a fallback, errors crash."},{"url":"fs.html#modified","label":"fs::modified","kind":"Function","description":"modified(path) — Modification time as Unix seconds, including fractions. Without a fallback, errors crash."},{"url":"fs.html#read","label":"fs::read","kind":"Function","description":"read(path) — Read the whole file as UTF-8. Without a fallback, read and encoding errors crash."},{"url":"fs.html#lines","label":"fs::lines","kind":"Function","description":"lines(path) — Read UTF-8 lines, without line endings. Without a fallback, errors crash."},{"url":"fs.html#list","label":"fs::list","kind":"Function","description":"list(dir, *, match = \"*\", recursive = :false) — List matching entries as paths joined to dir. Sort within each directory; recurse depth-first when requested. Patterns support * and ?. Without a fallback, errors crash."},{"url":"fs.html#write","label":"fs::write","kind":"Function","description":"write(path, text, *, mode = :replace, parents = :true) — Write text; return the path and UTF-8 byte count. :replace truncates, :append appends, :new requires a new file. Creates parent directories by default."},{"url":"fs.html#copy","label":"fs::copy","kind":"Function","description":"copy(source, target, *, overwrite = :true, parents = :true) — Copy a file or directory tree. Overwrite and create parent directories by default. Other failures crash."},{"url":"fs.html#move","label":"fs::move","kind":"Function","description":"move(source, target, *, overwrite = :false, parents = :true) — Rename a file or directory. Create parents by default; existing targets require overwrite = :true. Cross-filesystem moves may fail."},{"url":"fs.html#remove","label":"fs::remove","kind":"Function","description":"remove(path, *, recursive = :false) — Remove a file or empty directory; recursive = :true removes a directory tree. False if absent; other failures crash."},{"url":"fs.html#make_dir","label":"fs::make_dir","kind":"Function","description":"make_dir(path, *, parents = :true) — Create a directory and, by default, its parents. An existing directory is fine; other failures crash."},{"url":"fs.html","label":"fs","kind":"Page","description":"Filesystem paths, inspection, reading, and writing."},{"url":"env.html#args","label":"env::args","kind":"Function","description":"args() — Arguments after --, excluding the script name. Embedding hosts supply these in VM options."},{"url":"env.html#get","label":"env::get","kind":"Function","description":"get(name) — Read a variable. Missing names return fallback, :not_found; non-Unicode values return fallback, :encoding. Without a fallback, failures crash. Invalid names always crash."},{"url":"env.html#all","label":"env::all","kind":"Function","description":"all() — Snapshot Unicode environment variables, sorted by name. Keys are atoms; variables with non-Unicode names or values are omitted."},{"url":"env.html#platform","label":"env::platform","kind":"Function","description":"platform() — Host OS, such as :macos, :linux, or :windows."},{"url":"env.html","label":"env","kind":"Page","description":"Script arguments, environment variables, and the host platform."},{"url":"text.html#split","label":"text::split","kind":"Function","description":"split(text, separator = :null) — With :null, split on Unicode whitespace and discard empty fields. An explicit separator preserves empty fields; an empty separator splits into characters."},{"url":"text.html#join","label":"text::join","kind":"Function","description":"join(parts, separator = \"\") — Join a list of strings with the separator. An empty list produces an empty string."},{"url":"text.html#trim","label":"text::trim","kind":"Function","description":"trim(text) — Remove leading and trailing Unicode whitespace."},{"url":"text.html#replace","label":"text::replace","kind":"Function","description":"replace(text, from, to) — Replace every non-overlapping literal match. An empty from inserts at character boundaries, including both ends."},{"url":"text.html#find","label":"text::find","kind":"Function","description":"find(text, needle) — Zero-based character position of the first literal match; :null if absent. An empty needle matches at zero."},{"url":"text.html#starts_with","label":"text::starts_with","kind":"Function","description":"starts_with(text, prefix) — Whether text begins with the literal prefix."},{"url":"text.html#ends_with","label":"text::ends_with","kind":"Function","description":"ends_with(text, suffix) — Whether text ends with the literal suffix."},{"url":"text.html#lower","label":"text::lower","kind":"Function","description":"lower(text) — Unicode lowercase conversion, independent of locale."},{"url":"text.html#upper","label":"text::upper","kind":"Function","description":"upper(text) — Unicode uppercase conversion, independent of locale. May change character count."},{"url":"text.html","label":"text","kind":"Page","description":"Unicode string operations. Positions count characters, not bytes."},{"url":"json.html#parse","label":"json::parse","kind":"Function","description":"parse(text) — Objects become dicts with atom keys; arrays become lists; booleans and null become :true, :false, and :null. Invalid input gives fallback, :invalid, or crashes without a fallback."},{"url":"json.html#stringify","label":"json::stringify","kind":"Function","description":"stringify(value, *, pretty = :false) — Encode values, preserving dict order. Other atoms become JSON strings. pretty = :true indents. Functions, non-finite numbers, cycles, and excessive nesting crash."},{"url":"json.html","label":"json","kind":"Page","description":"Convert between JSON text and Hydra values."},{"url":"io.html#read","label":"io::read","kind":"Function","description":"read(*, stream = :stdin) — Read stdin to EOF, preserving line endings. Empty input produces an empty string."},{"url":"io.html#read_line","label":"io::read_line","kind":"Function","description":"read_line(*, stream = :stdin) — Read one line, removing its LF or CRLF ending. EOF produces :null; an empty line produces an empty string."},{"url":"io.html#lines","label":"io::lines","kind":"Function","description":"lines(*, stream = :stdin) — Read stdin to EOF as a list of lines, without line endings. This collects the entire input."},{"url":"io.html#write","label":"io::write","kind":"Function","description":"write(value, *, stream = :stdout) — Render one value without a newline to :stdout or :stderr, flush, and return its UTF-8 byte count. Failures crash."},{"url":"io.html#flush","label":"io::flush","kind":"Function","description":"flush(stream = :stdout) — Flush :stdout or :stderr. Failures crash."},{"url":"io.html#is_terminal","label":"io::is_terminal","kind":"Function","description":"is_terminal(stream = :stdout) — Whether :stdin, :stdout, or :stderr is connected to a terminal."},{"url":"io.html","label":"io","kind":"Page","description":"UTF-8 standard input, output, and error streams."},{"url":"time.html#now","label":"time::now","kind":"Function","description":"now() — Unix timestamp with fractional seconds. The system clock can jump."},{"url":"time.html#monotonic","label":"time::monotonic","kind":"Function","description":"monotonic() — Elapsed seconds from the host process’s first call. Use differences to measure durations; unrelated to calendar time."},{"url":"time.html#sleep","label":"time::sleep","kind":"Function","description":"sleep(seconds) — Wait a finite, nonnegative number of seconds while other trails run. Scheduling can make the actual wait longer."},{"url":"time.html#parse","label":"time::parse","kind":"Function","description":"parse(text) — Parse an RFC 3339 timestamp with an explicit offset or Z. Return Unix seconds; invalid input gives fallback, :invalid, or crashes without a fallback."},{"url":"time.html#format","label":"time::format","kind":"Function","description":"format(timestamp, format = \"%+\") — Format Unix seconds in UTC using strftime directives such as %Y-%m-%d %H:%M:%S. Default %+ produces RFC 3339. Invalid formats or dates crash."},{"url":"time.html","label":"time","kind":"Page","description":"Clocks, sleeping, and timestamp conversion. All durations use seconds."},{"url":"http.html#request","label":"http::request","kind":"Function","description":"request(method, url, *, body = :null, headers = {}, timeout = 30, max_bytes = 16777216) — Send a method string or atom, with an optional UTF-8 body. Response fields are .status, .headers, .body, and final .url. HTTP error statuses remain ordinary responses."},{"url":"http.html#get","label":"http::get","kind":"Function","description":"get(url, *, headers = {}, timeout = 30, max_bytes = 16777216) — GET shorthand for request. Response body must be UTF-8."},{"url":"http.html#post","label":"http::post","kind":"Function","description":"post(url, body, *, headers = {}, timeout = 30, max_bytes = 16777216) — POST a UTF-8 string. Set content-type explicitly; use json::stringify for JSON payloads."},{"url":"http.html#download","label":"http::download","kind":"Function","description":"download(url, path, *, headers = {}, timeout = 30, max_bytes = 16777216) — GET binary data to a file. Require a 2xx status, create parent directories, and replace the target only after the complete bounded download succeeds. Failure leaves an existing target intact."},{"url":"http.html","label":"http","kind":"Page","description":"HTTP and HTTPS requests, text responses, and binary downloads."},{"url":"atoms.html#control","label":":break","kind":"Control atom","description":":break — Stop the loop; for a parallel loop, cancel its other iterations."},{"url":"atoms.html#control","label":":continue","kind":"Control atom","description":":continue — End the current iteration."},{"url":"atoms.html#control","label":":return","kind":"Control atom","description":"[:return, …values] — Return the payload; no payload means :null."},{"url":"atoms.html#control","label":":reject","kind":"Control atom","description":"[:reject, msg] — Try the next candidate. Unhandled exhaustion reports every refusal and fails."},{"url":"atoms.html#control","label":":exit","kind":"Control atom","description":"[:exit, code] — Stop with status 0–255."},{"url":"atoms.html#control","label":":panic","kind":"Control atom","description":"[:panic, msg] — Stop with a diagnostic and status 1."},{"url":"atoms.html#true","label":":true","kind":"Atom","description":"Boolean true. Also returned by successful predicates."},{"url":"atoms.html#false","label":":false","kind":"Atom","description":"Boolean false; falsy."},{"url":"atoms.html#null","label":":null","kind":"Atom","description":"Absence or an empty result; falsy. Everything else is truthy, including 0 and empty collections."},{"url":"atoms.html#wait","label":":wait","kind":"Atom","description":"Wait until a sibling receives the message. Default for send."},{"url":"atoms.html#detach","label":":detach","kind":"Atom","description":"Queue for one eligible sibling and continue immediately."},{"url":"atoms.html#broadcast","label":":broadcast","kind":"Atom","description":"Queue one copy for each eligible sibling already spawned."},{"url":"atoms.html#replace","label":":replace","kind":"Atom","description":"Create or truncate a file. Default for fs::write."},{"url":"atoms.html#append","label":":append","kind":"Atom","description":"Append; create the file if absent."},{"url":"atoms.html#new","label":":new","kind":"Atom","description":"Create a new file; fail if it already exists."},{"url":"atoms.html#not_found","label":":not_found","kind":"Atom","description":"Path does not exist."},{"url":"atoms.html#denied","label":":denied","kind":"Atom","description":"Permission denied."},{"url":"atoms.html#exists","label":":exists","kind":"Atom","description":"Path already exists."},{"url":"atoms.html#is_dir","label":":is_dir","kind":"Atom","description":"A file operation encountered a directory."},{"url":"atoms.html#not_dir","label":":not_dir","kind":"Atom","description":"A directory operation encountered a non-directory."},{"url":"atoms.html#encoding","label":":encoding","kind":"Atom","description":"Invalid data, including non-UTF-8 text."},{"url":"atoms.html#io","label":":io","kind":"Atom","description":"Other I/O failure."},{"url":"atoms.html#stdin","label":":stdin","kind":"Atom","description":"Input stream for io readers and is_terminal."},{"url":"atoms.html#stdout","label":":stdout","kind":"Atom","description":"Default stream for io::write, flush, and is_terminal."},{"url":"atoms.html#stderr","label":":stderr","kind":"Atom","description":"Error output stream for io::write, flush, and is_terminal."},{"url":"atoms.html#invalid","label":":invalid","kind":"Atom","description":"Malformed JSON or timestamp."},{"url":"atoms.html#timeout","label":":timeout","kind":"Atom","description":"HTTP operation exceeded its time limit."},{"url":"atoms.html#dns","label":":dns","kind":"Atom","description":"HTTP hostname could not be resolved."},{"url":"atoms.html#tls","label":":tls","kind":"Atom","description":"TLS negotiation or certificate verification failed."},{"url":"atoms.html#network","label":":network","kind":"Atom","description":"Other HTTP connection or protocol failure."},{"url":"atoms.html#redirect","label":":redirect","kind":"Atom","description":"HTTP redirect limit or redirect failure."},{"url":"atoms.html#too_large","label":":too_large","kind":"Atom","description":"HTTP response exceeded max_bytes."},{"url":"atoms.html#http_status","label":":http_status","kind":"Atom","description":"A download received a non-2xx response. Other HTTP functions return the response normally."},{"url":"atoms.html","label":"Atoms & handlers","kind":"Page","description":"Atoms are ordinary values. Functions and handlers recognize particular names and list shapes."},{"url":"language.html#bindings","label":"Bindings & values","kind":"Language","description":":= declares; = assigns; _ = expression explicitly discards a result. Lists and dicts copy by value. Use &place to pass a reference; mutations through it reach the caller."},{"url":"language.html#calls","label":"Calls","kind":"Language","description":"Omit parentheses only for an outer statement or assignment RHS. Arguments use commas; nested calls require parentheses. A first argument starts on the callee’s line. Bare function names are values; zero-argument calls use ()."},{"url":"language.html#spacing","label":"Significant spacing","kind":"Language","description":"f -1 calls with a negative argument; f - 1 subtracts. f [1] calls with a list; f[1] indexes. f &x passes a reference; f & x is bitwise AND. The formatter preserves these distinctions."},{"url":"language.html#continuation","label":"Continuation","kind":"Language","description":"A single newline continues an expression whenever syntax permits. A blank or whitespace-only line stops it. Comment-only lines are transparent. Precedence stays unchanged."},{"url":"language.html#functions","label":"Functions & results","kind":"Language","description":"Blocks close with end; indentation is cosmetic. Parameters can have defaults, require a reference (&x), or collect positional arguments (xs*). Parameters after * or xs* are named-only. return is an ordinary builtin; a bare return calls it with no arguments."},{"url":"language.html#handlers","label":"Control values","kind":"Language","description":"A control builtin constructs an atom or tagged list. Binding, passing, or returning that value consumes it. An expression statement leaves it to a handler. Loop and return handlers stay within the current function; forward a request explicitly to let the caller handle it."},{"url":"language.html#overloads","label":"Overloads & rejection","kind":"Language","description":"Calls try candidates by signature; :reject or [:reject, msg] tries the next candidate. A successful fallback is silent. If all reject, an unconsumed rejection reports all messages and fails. Builtins can be shadowed; ::name explicitly selects a global builtin."},{"url":"language.html#modules","label":"Modules","kind":"Language","description":"use fs imports a module; fs::read(...) selects a function. use fs as files renames it; use fs as * imports its names. Standard modules: fs, env, text, json, io, time, and http."},{"url":"language.html#loops","label":"Branches & loops","kind":"Language","description":"Use if / else if / else, for item in items, or while condition. break() stops the nearest loop; continue() skips an iteration. Neither crosses a function boundary. There are no labeled breaks."},{"url":"language.html#trails","label":"Parallel trails","kind":"Language","description":"Each || column is an independent trail; rows do not synchronize. parallel waits for all trails; race cancels losers after a winner finishes. send and receive communicate within the block. Parallel loops support the same loop-control atoms."},{"url":"language.html#atoms","label":"Atoms & strings","kind":"Language","description":"Atoms use :name or :\"quoted name\". Bare names consume punctuation until whitespace, a delimiter (()[]{},:\"), or // / ||. A dict keeps the colon between key and value. Strings are double-quoted; \\(expression) interpolates a value."},{"url":"language.html","label":"Language","kind":"Page","description":"The rules you need to read and write Hydra."}];
